//! Task 3: bcrypt password primitives.
//!
//! Covers the 72-byte pre-hash rule, the 1024-byte maximum, cost 12, the
//! dummy hash, the four-worker admission bound, and both coexistence
//! directions (a Python-made hash verifies in Rust and a Rust-made hash
//! verifies in Python).

use std::io::Write;
use std::process::{Command, Stdio};

use sha2::{Digest, Sha256};
use verdaxis_read::auth::password::{self, PasswordError};

/// Generated by Python's `app.core.security.get_password_hash` for 73 bytes of
/// `a` (bcrypt cost 12 over SHA-256 of the UTF-8 bytes). A hash is not a
/// secret; the password is a fixed test value.
const PYTHON_HASH_OF_73_BYTES: &str =
    "$2b$12$0JSMT44V.5zqQ.Q1VR42oehd2MhDWRBLGAx5/k8wHh34wKrj0ylim";
/// Generated the same way for 72 bytes of `a`, which bcrypt hashes directly.
const PYTHON_HASH_OF_72_BYTES: &str =
    "$2b$12$6hrFqE4Rm2qUZRTLs4f1..KOgjt0IGdmpisw69MxliENLIKuxA0MS";

fn prehash(password: &str) -> Vec<u8> {
    Sha256::digest(password.as_bytes()).to_vec()
}

#[tokio::test]
async fn password_prehash_boundary_72_and_maximum_1024() {
    let raw_72 = "a".repeat(72);
    let raw_73 = "a".repeat(73);
    let maximum = "a".repeat(1024);
    let over_maximum = "a".repeat(1025);

    // 72 bytes are hashed directly by bcrypt.
    let hash_72 = password::hash(&raw_72).await.unwrap();
    assert!(hash_72.starts_with("$2b$12$"), "cost 12 and the 2b format");
    assert!(bcrypt::verify(raw_72.as_bytes(), &hash_72).unwrap());
    assert!(!bcrypt::verify(prehash(&raw_72), &hash_72).unwrap());
    assert!(password::verify(&raw_72, &hash_72).await);

    // 73 bytes are hashed as the 32-byte SHA-256 digest.
    let hash_73 = password::hash(&raw_73).await.unwrap();
    assert!(!bcrypt::verify(raw_73.as_bytes(), &hash_73).unwrap());
    assert!(bcrypt::verify(prehash(&raw_73), &hash_73).unwrap());
    assert!(password::verify(&raw_73, &hash_73).await);
    assert!(!password::verify(&"a".repeat(74), &hash_73).await);

    // Python-made hashes for the same passwords verify in Rust.
    assert!(password::verify(&raw_73, PYTHON_HASH_OF_73_BYTES).await);
    assert!(password::verify(&raw_72, PYTHON_HASH_OF_72_BYTES).await);
    assert!(!password::verify(&"a".repeat(71), PYTHON_HASH_OF_72_BYTES).await);

    // The maximum is accepted; one byte more is refused, never truncated.
    let hash_maximum = password::hash(&maximum).await.unwrap();
    assert!(password::verify(&maximum, &hash_maximum).await);
    assert_eq!(
        password::hash(&over_maximum).await.unwrap_err(),
        PasswordError::TooLong
    );
    assert_eq!(
        password::validate_bytes(&over_maximum),
        Err(PasswordError::TooLong)
    );
    assert_eq!(
        password::validate_bytes(&"a".repeat(7)),
        Err(PasswordError::TooShort)
    );
    assert_eq!(password::validate_bytes(&"a".repeat(8)), Ok(()));
    // Python's password floors (`Field(min_length=8)` and the manual
    // `len(...) < 8` checks) count characters, so a five-character password
    // of eight UTF-8 bytes is short. Only the ceiling stays in bytes.
    assert_eq!(
        password::validate_bytes("A1１２b"),
        Err(PasswordError::TooShort)
    );
    assert_eq!(password::validate_bytes("A1１２bbbb"), Ok(()));
    assert_eq!(password::validate_bytes(&maximum), Ok(()));
    assert_eq!(password::MAX_PASSWORD_BYTES, 1024);
    assert_eq!(password::BCRYPT_COST, 12);

    // A malformed stored hash is a failed comparison, never a panic.
    assert!(!password::verify("anything", "not-a-bcrypt-hash").await);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn password_worker_bound_is_four() {
    password::reset_worker_high_water();
    let mut workers = Vec::new();
    for _ in 0..8 {
        workers.push(tokio::spawn(async {
            password::hash(&"b".repeat(16)).await.unwrap()
        }));
    }
    for worker in workers {
        worker.await.unwrap();
    }
    assert_eq!(
        password::worker_high_water(),
        4,
        "eight concurrent hashes must saturate but never exceed four workers"
    );
}

#[tokio::test]
async fn dummy_hash_is_cost_twelve_built_once_and_matches_no_known_password() {
    let first = password::dummy_hash().await;
    assert!(first.starts_with("$2b$12$"), "cost 12 and the 2b format");
    assert_eq!(first.len(), 60, "a complete bcrypt hash");
    assert!(
        std::ptr::eq(first, password::dummy_hash().await),
        "the hash is built once per process"
    );
    for guess in ["", "password", "verdaxis-dummy-password-never-accepted"] {
        assert!(!password::verify(guess, first).await, "{guess:?}");
    }
}

#[tokio::test]
async fn python_issued_hash_verifies_in_rust() {
    let script = r#"
import json
from app.core.security import get_password_hash

print(json.dumps({
    "short_password": "correct horse battery staple",
    "short_hash": get_password_hash("correct horse battery staple"),
    "long_password": "a" * 73,
    "long_hash": get_password_hash("a" * 73),
}))
"#;
    let output = run_python(script, None);
    let document: serde_json::Value = serde_json::from_str(&output).unwrap();
    let short = document["short_password"].as_str().unwrap();
    let long = document["long_password"].as_str().unwrap();

    assert!(password::verify(short, document["short_hash"].as_str().unwrap()).await);
    assert!(password::verify(long, document["long_hash"].as_str().unwrap()).await);
    assert!(!password::verify("wrong password", document["short_hash"].as_str().unwrap()).await);
    assert!(!password::verify("wrong password", document["long_hash"].as_str().unwrap()).await);
}

#[tokio::test]
async fn rust_issued_hash_verifies_in_python() {
    let short = "correct horse battery staple";
    let long = "a".repeat(73);
    let document = serde_json::json!({
        "short_password": short,
        "short_hash": password::hash(short).await.unwrap(),
        "long_password": long,
        "long_hash": password::hash(&long).await.unwrap(),
    });
    let script = r#"
import json, sys
from app.core.security import verify_password

document = json.load(sys.stdin)
print(json.dumps({
    "short": verify_password(document["short_password"], document["short_hash"]),
    "long": verify_password(document["long_password"], document["long_hash"]),
    "wrong": verify_password(document["long_password"] + "!", document["long_hash"]),
    "cost_12": document["short_hash"].startswith("$2b$12$")
                     and document["long_hash"].startswith("$2b$12$"),
}))
"#;
    let output = run_python(script, Some(&document.to_string()));
    let verified: serde_json::Value = serde_json::from_str(&output).unwrap();
    assert!(verified["short"].as_bool().unwrap());
    assert!(verified["long"].as_bool().unwrap());
    assert!(!verified["wrong"].as_bool().unwrap());
    assert!(verified["cost_12"].as_bool().unwrap());
}

fn run_python(script: &str, input: Option<&str>) -> String {
    let python = std::env::var("RUST_TEST_PYTHON").unwrap_or_else(|_| "python3".into());
    let mut child = Command::new(python)
        .current_dir(concat!(env!("CARGO_MANIFEST_DIR"), "/../.."))
        .env("ENVIRONMENT", "test")
        .env("RELEASE_SHA", "test")
        .env(
            "JWT_SECRET",
            "phase3-task3-test-secret-at-least-32-characters",
        )
        .env("DATABASE_URL", "sqlite+aiosqlite:///:memory:")
        .args(["-c", script])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("the configured Python interpreter runs");
    if let Some(input) = input {
        child
            .stdin
            .as_mut()
            .unwrap()
            .write_all(input.as_bytes())
            .unwrap();
    }
    let output = child.wait_with_output().unwrap();
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8(output.stdout).unwrap()
}
